/*
 * placement.js — the short placement test (#/placement).
 *
 * Questions: LM.PLACEMENT from data/placement.js
 * (source: content/tests/placement.json, generated by
 * npm run build).
 *
 * Algorithm (LM.learn): start at A2; a right answer → the next question
 * one level up (at most C2), a wrong one or "I don't know" → one level down
 * (at least A1); 12 questions without repeats; when a level's pool runs out —
 * a question from the next level. From a level's pool first the questions outside the previous
 * attempt, and among them the skill seen least so far (grammar / vocabulary / reading,
 * pack v6 spec 13 section 1.3 of the reference app). Result: the average level of the last
 * 6 questions, rounded down.
 * The "level of a question" in the algorithm is the TARGET level (the one the test wanted
 * to ask about). When a level's pool is empty and a question comes from the next
 * level, the target level does not change — otherwise with a small pool the test
 * would "drift" to the other end of the scale. The last result is saved in the profile
 * (slm.placement). The test does NOT mark anything as "I know this".
 */
window.LM = window.LM || {};

(function (LM) {
  "use strict";

  const U = LM.utils;
  const el = U.el;

  const HASH = "#/placement";
  const LETTERS = ["A", "B", "C", "D", "E", "F", "G", "H"];

  function learn() { return LM.learn; }
  function pd() { return LM.profileData; }

  /** Questions from the file after checking (invalid ones are skipped). */
  function questions() {
    const data = LM.PLACEMENT;
    if (!data || !Array.isArray(data.questions)) return [];
    return data.questions.filter(function (q) {
      return q && typeof q.id === "string" && learn().LEVELS.indexOf(q.level) !== -1 &&
        Array.isArray(q.options) && q.options.length >= 2 &&
        Number.isInteger(q.correct) && q.correct >= 0 && q.correct < q.options.length;
    });
  }

  function questionById(id) {
    return questions().find(function (q) { return q.id === id; }) || null;
  }

  function parseRoute(hash) {
    return /^#\/placement\/?$/.test(hash || "") ? { kind: "test" } : null;
  }

  // State of the current attempt (in the tab's memory)
  let run = null;

  function start() {
    const last = pd().lastTest();
    run = {
      profileId: LM.app.getActiveProfile().id,
      // Questions of the previous attempt — avoided when the level's pool allows it (spec v6 13, 1.3)
      avoidIds: last && Array.isArray(last.answers) ? last.answers.map(function (a) { return a.id; }) : [],
      levelIndex: learn().LEVELS.indexOf(learn().START_LEVEL),
      used: new Set(),
      asked: [],      // { q, levelIndex (target), chosen, correct }
      current: null,
      answered: false,
      finished: false,
      saved: null
    };
    nextQuestion();
  }

  function nextQuestion() {
    if (run.asked.length >= learn().TEST_LENGTH) return finish();
    const prev = run.asked[run.asked.length - 1];
    // Skill balance: the rarest in this attempt (grammar, vocabulary, reading)
    const skillCounts = {};
    run.asked.forEach(function (a) { const s = learn().skillOf(a.q); skillCounts[s] = (skillCounts[s] || 0) + 1; });
    const q = learn().pickQuestion(questions(), run.levelIndex, run.used, Math.random, !!(prev && prev.correct), { avoidIds: run.avoidIds, skillCounts: skillCounts });
    if (!q) return finish(); // the question pool ran out
    run.used.add(q.id);
    run.current = { q: q, levelIndex: run.levelIndex };
    run.answered = false;
  }

  function answer(chosen) {
    if (!run || run.answered) return;
    const cur = run.current;
    const correct = chosen === cur.q.correct;
    run.asked.push({ q: cur.q, levelIndex: cur.levelIndex, chosen: chosen, correct: correct });
    // Next target level: up after a right answer, down after a wrong one
    run.levelIndex = learn().nextLevelIndex(cur.levelIndex, correct);
    run.answered = true;
    render();
    focusLater(".lt-next");
  }

  function finish() {
    run.finished = true;
    run.current = null;
    if (!run.asked.length) return;
    const idx = learn().resultLevelIndex(run.asked.map(function (a) { return a.levelIndex; }));
    run.saved = pd().saveTest({
      date: learn().today(),
      level: learn().LEVELS[idx],
      answers: run.asked.map(function (a) { return { id: a.q.id, level: a.q.level, chosen: a.chosen, correct: a.correct }; })
    });
    if (run.saved && LM.trailStore) LM.trailStore.setStart(run.saved.level, "test"); // the test result sets the trail's start (spec v7 13, 3.2)
    LM.markActivity(); // a finished test = a study day
    if (LM.celebrate) LM.celebrate.check({ event: "test", level: run.saved && run.saved.level });
  }

  function focusLater(selector) {
    setTimeout(function () { const b = document.querySelector(selector); if (b) b.focus(); }, 0);
  }

  // =====================================================================
  // SCREENS
  // =====================================================================

  const DISCLAIMER = "This is an approximate result. It is not an official test or certificate.";

  function header() {
    return el("header", { class: "tool-head" }, [
      el("h1", { class: "tool-title", text: "Placement test" }),
      el("p", { class: "tool-lead", text: "12 questions, about 6 minutes: grammar, vocabulary and short reading texts. The questions adapt to your answers: after a right answer the next one is harder, after a wrong one it is easier." })
    ]);
  }

  function renderIntro(view) {
    view.appendChild(header());
    const count = questions().length;
    const last = pd().lastTest();
    view.appendChild(el("section", { class: "card lt-card" }, [
      count
        ? el("p", { text: "You can choose “I don't know” – it is better than guessing. After each answer you see a short explanation." })
        : el("p", { text: "No test questions (data/placement.js). Run: npm run build" }),
      el("p", { class: "tool-note", text: DISCLAIMER }),
      el("div", { class: "tool-actions" }, [
        count ? el("button", { type: "button", class: "btn btn-primary", onclick: function () { start(); render(); focusLater(".lt-option"); } }, last ? "Take the test again" : "Start the test") : null,
        last ? el("button", { type: "button", class: "btn btn-secondary", onclick: function () { run = { finished: true, fromSaved: true, saved: last, profileId: LM.app.getActiveProfile().id }; render(); } }, "See the last result") : null
      ])
    ]));
    if (last) {
      view.appendChild(el("p", { class: "tool-note lt-last" }, [
        "Last result (" + LM.fmt.date(last.date) + "): ",
        el("strong", { text: last.level }),
        " – approximate."
      ]));
    }
  }

  function renderQuestion(view) {
    const cur = run.current;
    const n = run.asked.length + (run.answered ? 0 : 1);
    const total = learn().TEST_LENGTH;
    const q = cur.q;
    const last = run.answered ? run.asked[run.asked.length - 1] : null;

    view.appendChild(el("header", { class: "tool-head" }, [el("h1", { class: "tool-title", text: "Placement test" })]));
    // Progress dots: answered (right ✓ / wrong ✗ — not colour alone), current, upcoming
    const dots = [];
    for (let i = 0; i < total; i++) {
      const a = run.asked[i];
      const isCurrent = !run.answered ? i === run.asked.length : i === run.asked.length - 1;
      const cls = "lt-dot" + (a ? (a.correct ? " is-ok" : " is-bad") : "") + (isCurrent ? " is-current" : "");
      dots.push(el("li", { class: cls }, a ? LM.icon(a.correct ? "check" : "x", { size: 12 }) : null));
    }
    view.appendChild(el("div", { class: "lt-progress" }, [
      el("ol", { class: "lt-dots", "aria-hidden": "true" }, dots),
      el("span", { class: "progress-text", text: "Question " + n + " of " + total }),
      el("span", { class: "visually-hidden", text: "Right so far: " + run.asked.filter(function (a) { return a.correct; }).length + " of " + run.asked.length + "." })
    ]));

    const options = q.options.map(function (text, i) {
      let state = "";
      if (last) {
        if (i === q.correct) state = " is-correct";
        else if (i === last.chosen) state = " is-wrong";
      }
      return el("li", null, el("button", {
        type: "button",
        class: "lt-option" + state,
        disabled: !!last,
        "aria-label": LETTERS[i] + ": " + text + (last && i === q.correct ? " (right answer)" : last && i === last.chosen ? " (your answer)" : ""),
        onclick: function () { answer(i); }
      }, [
        el("span", { class: "lt-letter", "aria-hidden": "true" }, last && (i === q.correct || i === last.chosen) ? LM.icon(i === q.correct ? "check" : "x", { size: 16 }) : LETTERS[i]),
        el("span", { class: "lt-option-text", text: text }),
        last && i === q.correct ? el("span", { class: "lt-tag is-ok", "aria-hidden": "true", text: "Right" }) : null,
        last && i === last.chosen && i !== q.correct ? el("span", { class: "lt-tag is-bad", "aria-hidden": "true", text: "Your answer" }) : null
      ]));
    });

    const body = [
      // Reading: a short text in a box above the question (spec v6 13, 1.2)
      q.passage ? el("div", { class: "lt-passage", lang: LM.APP.targetLang }, [
        el("p", { class: "lt-passage-label", lang: "en", text: "Read the text:" }),
        el("p", { class: "lt-passage-text", text: q.passage })
      ]) : null,
      el("p", { class: "lt-question", id: "lt-question", text: q.question }),
      el("ol", { class: "lt-options", "aria-labelledby": "lt-question" }, options)
    ];
    if (!last) {
      body.push(el("div", { class: "tool-actions" }, el("button", { type: "button", class: "btn btn-secondary", onclick: function () { answer(-1); } }, "I don't know")));
    } else {
      body.push(el("div", { class: "lt-feedback " + (last.correct ? "is-ok" : "is-bad"), role: "status" }, [
        el("p", { class: "lt-verdict" }, [
          el("span", { class: "c1-mark " + (last.correct ? "is-ok" : "is-bad"), "aria-hidden": "true" }, LM.icon(last.correct ? "check" : "x", { size: 14 })),
          el("strong", { text: last.correct ? "Right!" : last.chosen === -1 ? "That's fine – the right answer is " + LETTERS[q.correct] + "." : "Not quite. The right answer is " + LETTERS[q.correct] + "." })
        ]),
        q.explanation ? el("p", { text: q.explanation }) : null
      ]));
      body.push(el("div", { class: "tool-actions" }, el("button", {
        type: "button",
        class: "btn btn-primary lt-next",
        onclick: function () { nextQuestion(); render(); focusLater(run.finished ? ".lt-result .btn-primary" : ".lt-option"); }
      }, run.asked.length >= total ? "See the result" : "Next")));
    }
    view.appendChild(el("section", { class: "card lt-card" }, body));
  }

  function renderResult(view) {
    view.appendChild(header());
    const saved = run.saved;
    if (!saved) { run = null; return renderIntro(view); }
    const level = saved.level;
    const levelData = LM.syl.level(level);
    const desc = levelData ? levelData.goal : "";

    // Wrong questions (from the result saved in the profile, so it also works after a reload)
    const wrong = saved.answers.filter(function (a) { return !a.correct; })
      .map(function (a) { return { a: a, q: questionById(a.id) }; })
      .filter(function (x) { return x.q; });

    const addBtn = wrong.length ? el("button", {
      type: "button",
      class: "btn btn-secondary",
      onclick: function () { addWrongToJournal(wrong, addBtn); }
    }, "Add the wrong questions to the mistake log") : null;

    view.appendChild(el("section", { class: "card lt-card lt-result lvl-" + level, "aria-live": "polite" }, [
      el("p", { class: "lt-result-label", text: "Estimated level:" }),
      el("p", { class: "lt-result-level" }, [el("strong", { class: "lt-result-code", text: level }), el("span", { class: "lt-result-note", text: "orientacyjnie" })]),
      desc ? el("p", { class: "tool-lead" }, U.formatText(desc)) : null,
      LM.syl.isAvailable(level) ? null : el("p", { class: "lt-result-soon", role: "note", text: level + " is on its way, so its pages are not written yet. Until then, the trail starts from the highest available level, and the " + level + " page shows what it will cover." }),
      skillBreakdown(saved.answers),
      el("p", null, el("a", { class: "wiki-link", href: LM.app.levelHash(level) + "" }, "What to know at " + level)),
      el("div", { class: "tool-actions" }, [
        el("a", { class: "btn btn-primary", href: LM.trail ? LM.trail.HASH : LM.app.levelHash(level), onclick: function () { if (LM.trailStore) LM.trailStore.setStart(level, "test", true); } }, "Start the trail at " + level),
        el("button", { type: "button", class: "btn btn-secondary", onclick: function () { start(); render(); focusLater(".lt-option"); } }, "Take the test again")
      ]),
      el("p", { class: "tool-note", text: DISCLAIMER + " Result from " + LM.fmt.date(saved.date) + "." })
    ]));

    // Short animation of the level code (GSAP; none with reduced motion)
    LM.motion.run([], function (gsap, reduce) {
      if (!gsap || reduce) return;
      gsap.from(view.querySelector(".lt-result-code"), { scale: 0.6, autoAlpha: 0, duration: 0.6, ease: "back.out(1.8)", clearProps: "all" });
      gsap.from(view.querySelectorAll(".lt-result > :not(.lt-result-level)"), { autoAlpha: 0, y: 8, duration: 0.4, stagger: 0.05, delay: 0.2, clearProps: "all" });
    });

    view.appendChild(el("section", { class: "card lt-card" }, [
      el("h2", { class: "section-title", text: wrong.length ? "Questions with a mistake (" + wrong.length + ")" : "No mistakes – well done!" }),
      wrong.length ? el("ol", { class: "lt-wrong" }, wrong.map(function (x) {
        const link = x.q.itemId && LM.mistakes ? LM.mistakes.itemLink(x.q.itemId) : null;
        return el("li", null, [
          x.q.passage ? el("details", { class: "lt-wrong-passage" }, [el("summary", null, "Text of the question"), el("p", { lang: LM.APP.targetLang, text: x.q.passage })]) : null,
          el("p", { class: "lt-wrong-q" }, [el("span", { class: "c1-chip", text: x.q.level }), " ", x.q.question]),
          el("p", { class: "journal-row is-right" }, [el("span", { class: "review-label", text: "Right answer: " }), el("strong", { text: x.q.options[x.q.correct] })]),
          x.a.chosen >= 0 ? el("p", { class: "journal-row is-wrong" }, [el("span", { class: "review-label", text: "Your answer: " }), el("span", { text: x.q.options[x.a.chosen] || "" })]) : el("p", { class: "tool-note", text: "You chose “I don't know”." }),
          link ? el("p", null, ["To review: ", link]) : null
        ]);
      })) : el("p", { class: "tool-note", text: "All your answers were right." }),
      addBtn ? el("div", { class: "tool-actions" }, addBtn) : null
    ]));
  }

  const SKILLS = [["grammar", "Grammar"], ["vocabulary", "Vocabulary"], ["reading", "Reading"]];

  /** Result split: "Grammar 5/7 (71%) · Vocabulary 2/3 · Reading 1/2" — a percentage only from 3 questions. */
  function skillBreakdown(answers) {
    const per = {};
    answers.forEach(function (a) {
      const q = questionById(a.id);
      const s = q ? learn().skillOf(q) : "grammar";
      per[s] = per[s] || { ok: 0, n: 0 };
      per[s].n++;
      if (a.correct) per[s].ok++;
    });
    const rows = SKILLS.filter(function (s) { return per[s[0]]; });
    if (!rows.length) return null;
    return el("div", { class: "lt-skills" }, [
      el("p", { class: "lt-skills-label", text: "Result by skill:" }),
      el("ul", { class: "lt-skills-list" }, rows.map(function (s) {
        const g = per[s[0]];
        return el("li", null, [
          el("span", { text: s[1] }),
          el("strong", { class: "num", text: g.ok + "/" + g.n }),
          g.n >= 3 ? el("span", { class: "lt-skills-pct num", text: Math.round(g.ok / g.n * 100) + "%" }) : null
        ]);
      })),
      rows.some(function (s) { return per[s[0]].n < 3; }) ? el("p", { class: "tool-note", text: "With fewer than 3 questions there is no percentage – that is too little to judge." }) : null
    ]);
  }

  /** Mistake log category of a question, from its syllabus topic. */
  function categoryOf(q) {
    return pd().journalCategoryOf(q.itemId);
  }

  /** Adds the wrong questions to the mistake log (no duplicates: the same question + the same answer). */
  function addWrongToJournal(wrong, btn) {
    let added = 0, skipped = 0;
    wrong.forEach(function (x) {
      const mine = x.a.chosen >= 0 ? x.q.options[x.a.chosen] : "I don't know";
      const ref = "test:" + x.q.id;
      if (pd().findDuplicate(ref, mine)) { skipped++; return; }
      const saved = pd().addEntry({
        context: x.q.question + "\n" + x.q.options.map(function (o, i) { return LETTERS[i] + " – " + o; }).join(", "),
        myAnswer: mine,
        correct: LETTERS[x.q.correct] + " – " + x.q.options[x.q.correct],
        rule: x.q.explanation || "",
        source: "Placement test, " + x.q.level + " question",
        category: categoryOf(x.q),
        itemId: x.q.itemId || "",
        ref: ref
      });
      if (saved) added++;
    });
    LM.app.refreshLearning();
    btn.disabled = true;
    btn.textContent = added ? "Added to the mistake log: " + added + (skipped ? " (duplicates skipped: " + skipped + ")" : "") : "These questions are already in the log";
  }

  function render() {
    const view = document.getElementById("view");
    if (!LM.PLACEMENT) {
      // The 60 questions load only on entering #/placement
      view.className = "view tool-view lt-view";
      view.replaceChildren(el("p", { class: "tool-note", role: "status", text: "Loading the questions…" }));
      LM.loadModule("data/placement.js").then(function () {
        if (LM.state.view === "placement") render();
      }, function (err) { console.warn(err.message + " — run: npm run build"); LM.PLACEMENT = { version: 1, questions: [] }; if (LM.state.view === "placement") render(); });
      return;
    }
    const profile = LM.app.getActiveProfile();
    if (run && (!profile || run.profileId !== profile.id)) run = null; // a profile change = a new attempt
    view.className = "view tool-view lt-view";
    view.dataset.file = HASH;
    view.replaceChildren();
    if (!run) renderIntro(view);
    else if (run.finished) renderResult(view);
    else renderQuestion(view);
    document.title = "Placement test · " + LM.APP.appTitle;
    U.setScroll(0);
  }

  /** Entering the page from another view: start at the start screen. */
  function onEnter() {
    if (run && run.finished) run = null;
  }

  LM.placement = { HASH: HASH, parseRoute: parseRoute, render: render, onEnter: onEnter };
})(window.LM);
